const REQUIRED = ASSETS.map((asset) => ({ ...asset, url: new URL(asset.url, self.registration.scope).href }));
let filling = null, lastError = '';

async function status() {
  const cache = await caches.open(CACHE);
  const saved = new Set((await cache.keys()).map((request) => request.url));
  const present = REQUIRED.filter((asset) => saved.has(asset.url));
  return { type: 'cache-status', version: CACHE, ready: present.length === REQUIRED.length,
    cached: present.length, total: REQUIRED.length,
    cachedBytes: present.reduce((sum, asset) => sum + asset.size, 0),
    totalBytes: REQUIRED.reduce((sum, asset) => sum + asset.size, 0), error: lastError };
}

async function publish() {
  const message = await status();
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  clients.forEach((client) => client.postMessage(message));
}

async function download(asset, cache) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 90000);
  try {
    // Integrity keeps one build together, even if the server files change during installation.
    const response = await fetch(new Request(asset.url, {
      cache: 'reload', integrity: asset.integrity, signal: controller.signal,
    }));
    if (response.status !== 200) throw new Error(`Download failed: ${response.status}`);
    await cache.put(asset.url, response);
  } finally { clearTimeout(timeout); }
}

// An update copies every unchanged file from the previous offline copy (checked byte for byte against the new
// build), so only changed files need the network and the update finishes quickly.
async function reuse(asset, cache) {
  for (const name of await caches.keys()) {
    if (!name.startsWith(CACHE_PREFIX) || name === CACHE) continue;
    const old = await (await caches.open(name)).match(asset.url);
    if (!old) continue;
    const bytes = await old.arrayBuffer();
    const hash = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
    if ('sha256-' + btoa(String.fromCharCode(...hash)) !== asset.integrity) continue;
    await cache.put(asset.url, new Response(bytes, { status: 200, headers: old.headers }));
    return true;
  }
  return false;
}

function fill(tries = 1) {
  return filling ??= (async () => {
    const cache = await caches.open(CACHE);
    for (let attempt = 0; attempt < tries; attempt++) {
      lastError = '';
      for (const asset of REQUIRED) {
        if (await cache.match(asset.url)) continue;
        try { if (!(await reuse(asset, cache))) await download(asset, cache); }
        catch (error) { lastError = error.name; console.warn('Offline save failed:', asset.url, error); }
        await publish();
        if (lastError === 'QuotaExceededError') break;
      }
      if ((await status()).ready || lastError === 'QuotaExceededError') break;
    }
    return status();
  })().finally(() => { filling = null; });
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const saved = await fill(3);
    // An incomplete update must never replace the working offline copy.
    // Partial downloads remain cached so the next installation can resume them.
    if (!saved.ready) throw new Error('Offline installation incomplete');
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    if (!(await status()).ready) throw new Error('Required offline files are missing');
    for (const name of await caches.keys()) {
      if (name.startsWith(CACHE_PREFIX) && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
    await publish();
  })());
});

async function rangeResponse(response, range) {
  const blob = await response.blob();
  const match = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  let start, end;
  if (match && (match[1] || match[2])) {
    if (match[1]) {
      start = Number(match[1]);
      end = match[2] ? Math.min(Number(match[2]), blob.size - 1) : blob.size - 1;
    } else {
      start = Math.max(0, blob.size - Number(match[2]));
      end = blob.size - 1;
    }
  }
  const headers = new Headers(response.headers);
  headers.set('Accept-Ranges', 'bytes');
  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start < 0 || start > end || start >= blob.size) {
    headers.set('Content-Range', `bytes */${blob.size}`);
    headers.set('Content-Length', '0');
    return new Response(null, { status: 416, headers });
  }
  headers.set('Content-Range', `bytes ${start}-${end}/${blob.size}`);
  headers.set('Content-Length', String(end - start + 1));
  headers.delete('Content-Encoding');
  return new Response(blob.slice(start, end + 1), { status: 206, headers });
}

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // Navigation parameters (?frame=, etc.) share the saved page; explicit model versions match exactly.
    const asset = REQUIRED.find((candidate) => {
      const savedURL = new URL(candidate.url);
      return savedURL.pathname === url.pathname && (!url.searchParams.has('v') || savedURL.search === url.search);
    });
    if (!asset) return fetch(event.request);
    let response = await cache.match(asset.url);
    if (!response) {
      await download(asset, cache);
      response = await cache.match(asset.url);
    }
    // Saved code stays immutable until a complete new worker takes over.
    const range = event.request.headers.get('Range');
    return range ? rangeResponse(response, range) : response;
  })());
});

self.addEventListener('message', (event) => {
  if (event.data !== 'cache-status') return;
  event.waitUntil((async () => {
    const saved = await status();
    event.source?.postMessage(saved);
    // event.waitUntil keeps interrupted-download recovery alive when the app leaves the foreground.
    if (!saved.ready) await fill();
  })());
});
